$_ADMINLANG['twofa']['title'] = "Δύο παραγόντων Πιστοποίηση";
$_ADMINLANG['twofa']['introtext'] = "Η Δύο παραγόντων πιστοποίηση προσθέτει ένα παραπάνω επίπεδο προστασία στις συνδέσεις. Αφού ενεργοποιηθεί &amp; ρυθμίζεται για κάθε χρήστη διαχειριστή (κάθε χρήστης πρέπει να το ενεργοποιεί ανεξάρτητα), κάθε φορά που οι χρήστες θα συνδέονται θα τους ζητείται να εισάγουν και το username & password τους καθώς και ένα δεύτερο παράγοντα, όπως έναν κωδικό ασφαλείας. Υποστηρίζουμε ένα ευρύ φάσμα μεθόδων δύο Παραγόντων Πιστοποίησης παρακάτω.";
$_ADMINLANG['twofa']['enable'] = "Ενεργοποίηση ".$_ADMINLANG['twofa']['title'];
